        var wl = RPGACE.modules.webLookup;
        var webHit = !!(wl && wl.logic.takeChatTurn());
        if (!matched && !anatomyHit && !actionHit && !recipeGenHit && !dataHit && !webHit) return orig.apply(this, arguments);
