        L.doneWith(i).then(function() {
          card.innerHTML = '<div style="font-size:13px;color:var(--muted);">✓ Won\'t come back' + (i.kind === 'recommendation' ? ' · marked checked' : '') + '</div>';
        }).catch(function(e) { done.disabled = false; lib.ui._err(e); });
